SELECT list_id AS list_id , close_date AS close_date , CASE WHEN status_cd IN ('1','2','5') THEN manage_date ELSE null END AS manage_date , schedule_cd AS schedule_code , info_id AS info_id , cycle_cd AS cycle_code , title AS title , org_id AS mng_org_id , manager_id AS manager_id , person_id AS person_id , status_cd AS status_code , note AS note , company_id AS company_id , deadline_id AS deadline_id , CASE WHEN COALESCE(class_id,999) = 0 THEN '공모주' ELSE sch08_class_nm END AS class_name , COALESCE(appr_id,0) AS appr_id , COALESCE(appr_status_cd,'') AS appr_status_code , COALESCE(appr_status_nm,'') AS appr_status_name FROM ( SELECT sch04_list_id list_id , sch04_close_date close_date , sch04_manage_date manage_date , sch04_schedule_cd schedule_cd , sch04_info_id info_id , sch04_cycle_cd cycle_cd , sch04_title title , sch04_mng_org_id org_id , f_org_nm(sch04_mng_org_id, sch04_close_date) org_nm , sch04_manager_id manager_id , f_emp_kor_nm(sch04_manager_id) manager_nm , sch04_person_id person_id , f_emp_kor_nm(sch04_person_id) person_nm , sch04_status_cd status_cd , sch04_company_id company_id , sch04_deadline_id deadline_id , sch04_note note , sch04_appr_id appr_id , appr1.apr01_status_cd appr_status_cd , CASE WHEN COALESCE(appr1.apr01_status_cd,'X') != 'X' THEN f_cdnm('AprStatusCode', appr1.apr01_status_cd, sch04_company_id, f_sysdate()) ELSE null END appr_status_nm , CASE WHEN sch04_schedule_cd = '5' THEN 0 ELSE sch01_class_id END class_id FROM sch04_list LEFT OUTER JOIN sch01_info ON sch01_info_id = sch04_info_id LEFT OUTER JOIN apr01_appr appr1 ON appr1.apr01_appr_id = sch04_appr_id WHERE sch04_company_id = #{companyId} AND sch04_schedule_cd NOT IN ('2','3','6','7') /*법규공시 제외 (2024.6.7 이용희 전무님)*/ AND ( ( #{manageCheck} = 'true' AND COALESCE(sch04_manage_date, sch04_close_date) BETWEEN #{startDate}::date AND #{endDate}::date ) OR ( #{manageCheck} != 'true' AND sch04_close_date BETWEEN #{startDate}::date AND #{endDate}::date ) ) AND COALESCE(sch01_private_yn,'false') = 'false' AND ( ( sch04_schedule_cd = '1' AND COALESCE(sch01_daily_yn,'false') = 'true' ) OR ( sch04_schedule_cd != '1' ) ) UNION ALL SELECT row_number() OVER (ORDER BY info_id) list_id , close_date close_date , close_date manage_date , schedule_cd schedule_cd , info_id info_id , cycle_cd cycle_cd , title title , org_id org_id , f_org_nm(org_id, close_date) org_nm , manager_id manager_id , f_emp_kor_nm(manager_id) manager_nm , manager_id person_id , f_emp_kor_nm(manager_id) person_nm , status_cd status_cd , company_id company_id , deadline_id deadline_id , '' note , null appr_id , '' appr_status_cd , '' appr_status_nm , class_id class_id FROM ( /* 스케줄정보 */ SELECT '1' schedule_cd , sch01_info_id info_id , close_date close_date , sch03_cycle_cd cycle_cd , sch01_title title , sch01_manager_id manager_id , CAST(f_get_empTrans(sch01_manager_id, close_date, 'org_code_id') AS NUMERIC) org_id , sch01_company_id company_id , sch03_deadline_id deadline_id , '0' status_cd , sch01_class_id class_id FROM ( SELECT sch01_info.* , sch03_deadline.* , f_get_std_date(sch03_deadline_id, #{startDate}, sch01_company_id) close_date FROM sch01_info INNER JOIN sch03_deadline ON sch03_info_id = sch01_info_id WHERE sch01_company_id = #{companyId} AND COALESCE(sch01_use_yn,'true') = 'true' AND sch03_cycle_cd NOT IN ('02','03','04','05','06') /*(주/월/분기/반기/연)제외*/ UNION ALL SELECT sch01_info.* , sch03_deadline.* , sch09_day close_date FROM sch01_info INNER JOIN sch03_deadline ON sch03_info_id = sch01_info_id INNER JOIN sch09_deadline_day ON sch09_deadline_id = sch03_deadline_id WHERE sch01_company_id = #{companyId} AND COALESCE(sch01_use_yn,'true') = 'true' AND sch03_cycle_cd IN ('02','03','04','05','06') /*(주/월/분기/반기/연)*/ AND sch09_day BETWEEN #{startDate}::date AND #{endDate}::date ) sch WHERE 1=1 AND COALESCE(sch01_private_yn,'false') = 'false' AND COALESCE(sch01_daily_yn,'false') = 'true' UNION ALL /* 공모주 */ SELECT '5' schedule_cd , info_id info_id , close_date close_date , '99' cycle_cd , title title , #{personId} manager_id , CAST(f_get_empTrans(#{personId}, close_date, 'org_code_id') AS NUMERIC) org_id , #{companyId} company_id , null deadline_id , '0' status_cd , 0 class_id FROM ( SELECT sch10_ipo_id info_id , sch10_demand_start_date close_date , '[수요예측] '||sch10_item_nm title FROM sch10_ipo WHERE sch10_demand_start_date <= #{endDate}::date AND sch10_demand_close_date >= #{startDate}::date AND COALESCE(sch10_cancel_yn,'false') != 'true' UNION ALL SELECT sch10_ipo_id info_id , sch10_subscription_start_date close_date , '[공모주청약] '||sch10_item_nm title FROM sch10_ipo WHERE sch10_subscription_start_date <= #{endDate}::date AND sch10_subscription_close_date >= #{startDate}::date AND COALESCE(sch10_cancel_yn,'false') != 'true' UNION ALL SELECT sch10_ipo_id info_id , sch10_pay_date close_date , '[공모주납입] '||sch10_item_nm title FROM sch10_ipo WHERE sch10_pay_date BETWEEN #{startDate}::date AND #{endDate}::date AND COALESCE(sch10_cancel_yn,'false') != 'true' UNION ALL SELECT sch10_ipo_id info_id , sch10_list_date close_date , '[공모주상장] '||sch10_item_nm title FROM sch10_ipo WHERE sch10_list_date BETWEEN #{startDate}::date AND #{endDate}::date AND COALESCE(sch10_cancel_yn,'false') != 'true' ) ipo WHERE ( ( #{personId} IN ( SELECT sch02_person_id FROM sch02_share WHERE sch02_info_id = info_id AND sch02_share_cd = '1' ) ) OR ( #{orgId} IN ( SELECT sch02_org_id FROM sch02_share WHERE sch02_info_id = info_id AND sch02_share_cd = '2' ) ) ) AND 'false' = f_get_empTrans(#{personId}, close_date, 'non_stay_yn') ) a WHERE close_date BETWEEN #{startDate}::date AND #{endDate}::date AND NOT EXISTS ( SELECT 1 FROM sch04_list WHERE sch04_company_id = company_id AND sch04_info_id = info_id AND sch04_manager_id = manager_id AND sch04_close_date = close_date ) ) sch LEFT OUTER JOIN sch08_class ON sch08_class_id = sch.class_id WHERE sch.company_id = #{companyId} AND ( ( #{personId} IN ( SELECT sch.person_id UNION ALL SELECT sch.manager_id UNION ALL SELECT sch02_person_id FROM sch02_share WHERE sch02_info_id = sch.info_id AND sch02_share_cd = '1' ) ) OR ( #{orgId} IN ( SELECT sch02_org_id FROM sch02_share WHERE sch02_info_id = sch.info_id AND sch02_share_cd = '2' ) ) ) AND 'Y' = CASE #{shareType} WHEN '1' THEN (CASE WHEN #{personId} IN (sch.person_id, sch.manager_id) THEN 'Y' ELSE 'N' END) WHEN '2' THEN (CASE WHEN #{personId} NOT IN (sch.person_id, sch.manager_id) THEN 'Y' ELSE 'N' END) ELSE 'Y' END AND status_cd LIKE #{statusCode}
AND class_id = #{classId}
AND ( ( #{exceptYn} = 'true' AND status_cd not in ('1','2','5') ) OR /* (1:완료/2:ICAM/5:해당없음) */ ( #{exceptYn} = 'false' ) ) AND ( ( #{cancelYn} = 'true' AND status_cd != '9' ) OR /* (9:취소) */ ( #{cancelYn} = 'false' ) ) AND CONCAT(title, org_nm, person_nm) ILIKE #{searchText} ORDER BY CASE WHEN status_cd in ('1','2','5') THEN manage_date ELSE close_date END , CASE WHEN sch08_seq IS NULL THEN 999 ELSE sch08_seq END , COALESCE(class_id,999) , title COLLATE "ko_KR.utf8"

SELECT sch04_list_id
  FROM sch04_list
 WHERE sch04_company_id = #{companyId}
   AND sch04_info_id    = #{infoId}
   AND sch04_manager_id = #{managerId}
   AND sch04_close_date = #{closeDate}
 ORDER BY sch04_list_id
 LIMIT 1

