UPDATE sch04_list
   SET sch04_status_cd   = #{statusCode}
     , sch04_manage_date = CASE WHEN #{statusCode} IN ('0','9') THEN sch04_close_date ELSE #{manageDate,jdbcType=DATE} END
     , sch04_person_id   = #{personId}
 WHERE sch04_list_id    = #{listId}
   AND sch04_company_id = #{companyId}

mapper.select:
SELECT sch04_list_id AS list_id , sch04_manage_date AS manage_date , sch04_close_date AS close_date , sch04_class_nm AS class_name , sch04_title AS title , sch04_schedule_cd AS schedule_code , sch04_info_id AS info_id , sch04_deadline_id AS deadline_id , sch04_status_nm AS status_name , sch04_note AS note , sch04_appr_id AS appr_id , sch04_appr_status_nm AS appr_status_name FROM ( SELECT sch04_list.* , CASE WHEN sch04_schedule_cd = '5' THEN 0 ELSE sch01_class_id END AS sch04_class_id , CASE WHEN sch04_schedule_cd = '5' THEN '공모주' ELSE sch08_class_nm END AS sch04_class_nm , f_cdnm('ScheduleStatusCode', sch04_status_cd, sch04_company_id, f_today()) AS sch04_status_nm , f_cdnm('AprStatusCode ', apr01_status_cd, sch04_company_id, f_today()) AS sch04_appr_status_nm , COALESCE(sch08_seq, 999) AS seq FROM sch04_list LEFT OUTER JOIN apr01_appr ON apr01_appr_id = sch04_appr_id LEFT OUTER JOIN ( SELECT * FROM sch01_info LEFT OUTER JOIN sch08_class ON sch08_class_id = sch01_class_id WHERE sch01_company_id = #{companyId} ) sch ON sch01_info_id = sch04_info_id WHERE sch04_company_id = #{companyId} AND sch04_person_id = #{personId} AND sch04_manage_date BETWEEN #{startDate}::date AND #{endDate}::date AND sch04_status_cd LIKE #{statusCode} AND CONCAT(sch04_title, sch04_note) ILIKE #{searchText} AND ( ( sch04_schedule_cd != '5' AND /*(5:공모주)가 아닌 경우*/ COALESCE(sch01_private_yn,'false') != 'true' AND COALESCE(sch01_daily_yn ,'false') = 'true' ) OR ( sch04_schedule_cd = '5' ) ) ) t WHERE 1=1
AND sch04_class_id = #{classId}
ORDER BY sch04_manage_date, seq, sch04_title COLLATE "ko_KR.utf8"
